import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as l,o as a,af as e,b as s,w as r,a as d,G as h,ag as u}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"组 4 · 知识接地","description":"模型的参数知识静态且有截止日期——本组把回答接到你自己的证据上：可追溯的检索链与可重跑的更新管道。","frontmatter":{"title":"组 4 · 知识接地","description":"模型的参数知识静态且有截止日期——本组把回答接到你自己的证据上：可追溯的检索链与可重跑的更新管道。","domain":"tech","tags":["grounding","navigation"],"navOrder":40,"topicId":"grounding","layer":"4","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/11-rag"}],"prerequisites":["streaming"],"next":["embeddings-retrieval","rag","advanced-retrieval","tool-execution"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/04-grounding/index.md","filePath":"zh/tech/04-grounding/index.md","lastUpdated":1788326832000}'),g={name:"zh/tech/04-grounding/index.md"};function c(p,t,E,m,q,A){const n=i("Mermaid");return a(),l("div",null,[t[1]||(t[1]=e('<h1 id="组-4-·-知识接地" tabindex="-1">组 4 · 知识接地 <a class="header-anchor" href="#组-4-·-知识接地" aria-label="Permalink to &quot;组 4 · 知识接地&quot;">​</a></h1><blockquote><p><strong>所在组</strong>：组 4 · 知识接地（读世界） ｜ <strong>上一组出口</strong>：能写并验证输入输出 schema，并交付一次可取消、可观测的端到端交互（组 2–3） ｜ <strong>本组出口</strong>：能构建可追溯的检索链和更新路径 <strong>前置</strong>：<a href="./../02-inference-interface/streaming.html">流式响应</a> ｜ <strong>下一步</strong>：<a href="./embeddings-retrieval.html">嵌入与检索</a>、<a href="./../05-action/tool-execution.html">工具执行工程</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>本组解决一个具体症状：<strong>回答缺少私有或新事实</strong>。模型的参数知识（parametric memory）在训练结束那一刻就冻结了——它不知道你的工单、你的代码、上周改过的文档。本组把回答接到外部证据上：先检索、后生成、答案带出处、数据更新后可重建。</p><p>RAG 原论文（Lewis et al.，NeurIPS 2020）把这个结构命名为&quot;参数记忆 + 非参数记忆&quot;：参数记忆是预训练的生成模型，非参数记忆是可用检索器访问的外部向量索引（论文中即维基百科的稠密向量索引）。论文同时指出，纯参数模型&quot;为决策提供出处（provenance）&quot;和&quot;更新世界知识&quot;是两个未解问题——这正是本组要交付的两件事（检索链可追溯、更新路径可重跑）（arXiv:2005.11401，摘要已复核，retrievedAt 2026-09-01）。</p><p>本组与 <a href="./../05-action/tool-calling.html">Action 组</a>（05，写世界）共享&quot;让模型接触模型之外的东西&quot;这个直觉，但方向相反：<strong>读世界 vs 写世界</strong>。本组全部动作是&quot;读&quot;——切块、索引、检索、引用，默认无副作用；失败模式是&quot;答错或该拒答没拒答&quot;，不会破坏任何东西。Action 组才&quot;写世界&quot;（执行动作），失败模式是&quot;破坏状态&quot;。因此两组的验收口径不同：本组验收<strong>引用正确与拒答正确</strong>，Action 组验收<strong>权限受限与可恢复</strong>。</p>',6)),(a(),s(u,null,{default:r(()=>[h(n,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%E7%A6%BB%E7%BA%BF%E7%AE%A1%E9%81%93%5B%22%E7%A6%BB%E7%BA%BF%EF%BC%9A%E6%9B%B4%E6%96%B0%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20%20%20%20%20A%5B%E8%AF%AD%E6%96%99%5D%20--%3E%20B%5B%E5%88%87%E5%9D%97%5D%20--%3E%20C%5B%E5%B5%8C%E5%85%A5%5D%20--%3E%20D%5B(%E7%B4%A2%E5%BC%95%EF%BC%9A%E5%8E%9F%E6%96%87%2B%E5%90%91%E9%87%8F%2B%E5%85%83%E6%95%B0%E6%8D%AE)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E5%9C%A8%E7%BA%BF%E9%93%BE%E8%B7%AF%5B%22%E5%9C%A8%E7%BA%BF%EF%BC%9A%E6%A3%80%E7%B4%A2%E9%93%BE%22%5D%0A%20%20%20%20%20%20%20%20Q%5B%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%5D%20--%3E%20E%5B%E6%A3%80%E7%B4%A2%20top-k%5D%20--%3E%20F%5B%E8%BF%87%E6%BB%A4%EF%BC%9A%E6%9D%83%E9%99%90%2F%E7%A7%9F%E6%88%B7%5D%20--%3E%20G%5B%E9%87%8D%E6%8E%92%5D%20--%3E%20H%5B%E7%94%9F%E6%88%90%EF%BC%9A%E7%AD%94%E6%A1%88%E5%BF%85%E9%A1%BB%E5%B8%A6%E5%87%BA%E5%A4%84%5D%0A%20%20%20%20%20%20%20%20E%20--%3E%7C%E6%97%A0%E5%91%BD%E4%B8%AD%7C%20R%5B%E6%8B%92%E7%AD%94%EF%BC%9A%E5%AE%81%E5%8F%AF%E8%AF%B4%E4%B8%8D%5D%0A%20%20%20%20end%0A%20%20%20%20D%20--%3E%20E%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<h3 id="何时进入本组-何时不进" tabindex="-1">何时进入本组 / 何时不进 <a class="header-anchor" href="#何时进入本组-何时不进" aria-label="Permalink to &quot;何时进入本组 / 何时不进&quot;">​</a></h3><ul><li><strong>进</strong>：回答需要私有语料（产品文档、工单、代码）、需要引用出处、或知识频繁更新。</li><li><strong>不进</strong>：回答不稳定、无法解析——先回 <a href="./../03-context/">组 3 上下文</a>（输出形状的落点：<a href="./../02-inference-interface/structured-output.html">结构化输出</a>）；还没接入产品交互——先去 <a href="./../02-inference-interface/">组 2 推理与接口</a>；要让系统执行动作——去 <a href="./../05-action/tool-calling.html">组 5 行动</a>。</li></ul><h3 id="症状-→-主题导航" tabindex="-1">症状 → 主题导航 <a class="header-anchor" href="#症状-→-主题导航" aria-label="Permalink to &quot;症状 → 主题导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>去哪</th><th>读完你能</th></tr></thead><tbody><tr><td>想按&quot;意思&quot;搜文档，关键词搜不到</td><td><a href="./embeddings-retrieval.html">嵌入与检索</a></td><td>搭一个带元数据过滤与无命中路径的向量检索入口</td></tr><tr><td>要做&quot;基于我们文档回答&quot;的产品功能</td><td><a href="./rag.html">RAG：检索增强生成</a></td><td>跑通 ingest→chunk→embed→retrieve→generate 全链，答案带出处、无命中拒答</td></tr><tr><td>基线 RAG 召回质量不够 / 错误码查不到</td><td><a href="./advanced-retrieval.html">高级检索</a></td><td>用混合检索、查询改写、重排把召回提上去，权限钉在检索层</td></tr></tbody></table><h3 id="决策表-知识注入方式对比" tabindex="-1">决策表：知识注入方式对比 <a class="header-anchor" href="#决策表-知识注入方式对比" aria-label="Permalink to &quot;决策表：知识注入方式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>方向</th><th>控制权</th><th>状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>长上下文直塞</td><td>语料 → prompt（整批搬运）</td><td>提示层拼接，无检索控制</td><td>每次请求重发全文</td><td>整个语料进模型上下文</td><td>最低（单批小语料）</td></tr><tr><td>RAG（本组）</td><td>查询 → 检索 → 上下文（选择性搬运）</td><td>索引、切块、过滤全自管</td><td>索引是派生物，可重建</td><td>只送命中片段与元数据</td><td>中（嵌入 + 索引 + 更新管道）</td></tr><tr><td>微调</td><td>语料 → 参数（改写模型本身）</td><td>训练配方与数据配比</td><td>固化进权重，更新即重训</td><td>语料进入训练流程</td><td>最高（详见 Learn LLM 桥接）</td></tr></tbody></table><p>选型原则：<strong>从最低复杂度起步</strong>。语料小到一批能塞进上下文（Anthropic 给的参考线是约 200,000 token，配合 prompt caching），就先直塞；语料大、更新频繁、要引用，才上 RAG；要改的是行为风格而不是事实，才考虑微调。</p><h3 id="历史版本里程碑" tabindex="-1">历史版本里程碑 <a class="header-anchor" href="#历史版本里程碑" aria-label="Permalink to &quot;历史版本里程碑&quot;">​</a></h3><ul><li>2016：HNSW 近似最近邻索引结构发表（Malkov &amp; Yashunin, arXiv:1603.09320），成为向量库的主流索引底座（retrievedAt 2026-09-01）。</li><li>2020：RAG 论文发表（Lewis et al., NeurIPS 2020, arXiv:2005.11401），确立&quot;参数记忆 + 非参数记忆&quot;框架（retrievedAt 2026-09-01）。</li><li>2024-09-19：Anthropic 发表 Contextual Retrieval（上下文化切块 + BM25 + 重排的组合方案）；实验数据见 <a href="./advanced-retrieval.html">高级检索</a>。发布日期经多个独立转载源交叉核验（retrievedAt 2026-09-01）。</li><li>2026-09：v6 重构（Issue #116）把 v5 的六层金字塔改组为十组依赖结构，本组由&quot;层 3 · 知识接地&quot;改称&quot;组 4 · 知识接地（读世界）&quot;，读写分离的边界与验收口径不变。</li></ul><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本组最小实战是 <a href="./embeddings-retrieval.html">嵌入与检索</a> 的零 key 示例：一个纯 TypeScript 的确定性向量检索器，15 分钟内可在干净环境跑通。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 保存 embeddings-retrieval 页的完整示例为 embeddings-retrieval.ts，然后：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> embeddings-retrieval.ts</span></span></code></pre></div><p>验收：三组输出齐全——词法重合的查询命中正确文档并带来源、改写过的查询（零词面重合）正确走&quot;无命中&quot;路径、语料外问题正确拒答。跑通后你已经见过本组最核心的两个行为：<strong>分数不是真理</strong>（相似度高只代表&quot;像&quot;）与<strong>无命中是路径而不是异常</strong>。</p><p>各主题的使用段都遵循同一约束：零 API key、单文件自包含、确定性输出、正常路径与负例路径成对出现。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>在能力变换链上，本组把组 2 的&quot;一次交互&quot;升级为&quot;一次有依据的交互&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>离线：语料 → 切块 → 嵌入 → 索引（原文 + 向量 + 元数据 + 内容指纹）</span></span>
<span class="line"><span>在线：问题 → 检索 top-k → 过滤（权限/租户）→ 重排 → 生成（带引用）</span></span>
<span class="line"><span>更新：文档变更 → 指纹对比 → 增量重建索引条目 → 陈旧条目删除</span></span></code></pre></div><ul><li><strong>不变量 1：要么引用，要么明说没有</strong>。每条答案必须能回链到源文档；检索不到就拒答，不允许模型凭参数记忆补洞。</li><li><strong>不变量 2：权限过滤发生在检索时</strong>。有权限的文档不能被没权限的人检索到；过滤发生在召回阶段，不是生成后再藏。</li><li><strong>不变量 3：索引是派生物</strong>。索引由&quot;语料 + 切块策略 + 嵌入模型版本&quot;三者决定，任何一项变化都要重建；索引永远可以从语料重跑出来。</li></ul><p><strong>出口标准（Exit criteria）</strong>：能构建可追溯的检索链和更新路径——任意一条答案能回链到源文档与 chunk；该拒答的问题拒答；语料更新后有一条可重跑的重建管道。</p><p>各主题的原理细节：<a href="./embeddings-retrieval.html">embeddings-retrieval</a>、<a href="./rag.html">rag</a>、<a href="./advanced-retrieval.html">advanced-retrieval</a>。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>进入本层前，先用三条诊断定位该读哪页。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：模型编造私有事实，说得还很自信。 <strong>证据</strong>：把同一问题分别问裸模型和带检索链的产品，对比答案；查检索日志确认是否命中。 <strong>处理</strong>：确认问题真的走了检索链路；按 <a href="./rag.html">rag</a> 补无命中拒答与引用约束。 <strong>完成标准</strong>：golden set 里&quot;该拒答&quot;的题目全部拒答，&quot;该命中&quot;的题目答案带正确出处。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：答案带引用，但引用的段落和答案对不上。 <strong>证据</strong>：抽样答案，回放其 chunk id 指向的原文；检查 chunk 边界是否把语义切断。 <strong>处理</strong>：按 <a href="./embeddings-retrieval.html">embeddings-retrieval</a> 的 chunk 策略重切（结构边界优先、带重叠），用稳定 id 重建索引。 <strong>完成标准</strong>：20 条抽检答案的引用全部指向支撑该答案的段落。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：文档已经改了，答案还是旧口径。 <strong>证据</strong>：对比索引条目的时间戳/内容指纹与文档当前版本。 <strong>处理</strong>：按 <a href="./rag.html">rag</a> 的更新管道（内容指纹 + 增量重建 + 陈旧条目删除）修索引管道。 <strong>完成标准</strong>：文档更新触发的重建跑完后，同一问题的答案指向新版本文档。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="四级阅读路线" tabindex="-1">四级阅读路线 <a class="header-anchor" href="#四级阅读路线" aria-label="Permalink to &quot;四级阅读路线&quot;">​</a></h3><ul><li><strong>Beginner</strong>：<a href="./embeddings-retrieval.html">嵌入与检索</a>（先跑通一次向量检索）。</li><li><strong>Builder</strong>：<a href="./rag.html">RAG：检索增强生成</a>（把检索接进生成循环）。</li><li><strong>Operator</strong>：各主题&quot;开发&quot;段的 runbook → <a href="./../08-production/evaluation.html">评估（桥接）</a>（把引用正确率变成上线门）。</li><li><strong>Researcher</strong>：<a href="./advanced-retrieval.html">高级检索</a> → Learn LLM 的 RAG 原理章（机制与数学，本仓不重复）。</li></ul><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>&quot;长上下文直塞的参考线约 200,000 token&quot;来自 Anthropic Contextual Retrieval 博文（retrievedAt 2026-09-01）；具体模型的窗口与缓存价格以官方文档当天页面为准。</li><li>混合检索与重排的收益数字是 Anthropic 在其语料与配置下的实验结果，迁移到你自己的语料前先跑 golden set 对照。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><p>本组回答&quot;怎么让结果有依据&quot;，不回答&quot;嵌入模型的训练目标与向量几何&quot;（→ <a href="https://llm.zenheart.site/chapters/11-rag" target="_blank" rel="noreferrer">Learn LLM</a>）、&quot;评估方法与 benchmark&quot;（→ <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>）、&quot;执行动作与权限&quot;（→ <a href="./../05-action/tool-calling.html">组 5 行动</a>）。</p>`,35))])}const _=o(g,[["render",c]]);export{k as __pageData,_ as default};
